def missing_perplexity_3(required,present):
    if type(required) is not tuple or type(present) is not tuple: raise TypeError('container_invalid')
    if any(type(value) is not str for value in required+present): raise TypeError('item_invalid')
    if any(not value.strip() for value in required+present): raise ValueError('item_blank')
    if len(set(required))!=len(required) or len(set(present))!=len(present): raise ValueError('duplicate')
    return tuple(value for value in required if value not in present)

def bounded_exact_match_4(values,cap):
    if type(values) is not tuple or type(cap) is not int: raise TypeError('input_invalid')
    if type(cap) is bool or cap<=0: raise ValueError('cap_invalid')
    if any(type(value) is not int or type(value) is bool for value in values): raise TypeError('value_invalid')
    if any(value<0 for value in values): raise ValueError('negative')
    return min(sum(values),cap)

def gate_precision_5(scores,threshold):
    if type(scores) is not tuple or type(threshold) is not int or type(threshold) is bool: raise TypeError('input_invalid')
    if not scores: raise ValueError('scores_empty')
    if threshold<0 or threshold>100: raise ValueError('threshold_invalid')
    if any(type(score) is not int or type(score) is bool for score in scores): raise TypeError('score_invalid')
    if any(score<0 or score>100 for score in scores): raise ValueError('score_range')
    return all(score>=threshold for score in scores)

